        transplant_count = (SELECT COUNT(*) FROM transplant_matching t2 JOIN administrative_and_review a2 ON t2.match_rec_registry = a2.adm_rev_registry WHERE t2.match_status = 'Completed' AND a2.tx_cen_code = v_tx_cen_code),
